"""Four authored constructions for the lower half of printed page 222."""
from math import cos, dist, radians, sin, sqrt
from circle_lessons import circle_each, solution
from chord_followup import chord, circum
from midpoint_lessons import coordinates, drawing, edges, foot, mid


def frame(points, labels, lines, fills=()):
    return drawing({k: points[k] for k in labels}, lines, fills)


def final_four():
    a,b,c=(0,0),(3,5),(8,0)
    o=circum(a,b,c)
    d=coordinates(a,c,dist(a,b)/(dist(a,b)+dist(b,c)))
    e=chord(o,b,(d[0]-b[0],d[1]-b[1]))
    p=dict(A=a,B=b,C=c,D=d,E=e,O=o)
    abc=edges('ABC')
    first=solution(910,'BD — биссектриса треугольника ABC, D лежит на AC. Докажи формулу BD²=AB·BC−AD·DC.',
        'Произведение AB·BC равно BD·BE, где E — второе пересечение луча BD с описанной окружностью. Из BD·DE=AD·DC получаем требуемую разность.',
        'Чем можно дополнить чертёж, чтобы произведение AD·DC появилось из пересечения двух хорд?',
        [('Какие углы равны после продолжения биссектрисы?', 'Проведи окружность через A, B, C и продолжи BD до второй точки E. Углы ABE и DBC равны по условию. Вписанные углы AEB и ACB опираются на одну хорду AB. Так как D лежит на AC, угол ACB равен DCB.',
          'Биссектриса проходит внутри треугольника. На её луче точки расположены в порядке B, D, E.'),
         ('Откуда взять произведение AB·BC?', 'Из двух пар равных углов следует подобие ABE и DBC: A соответствует D, B — B, E — C. Поэтому AB/BD=BE/BC и AB·BC=BD·BE.',
          'При составлении пропорции стороны AB и BE первого треугольника сопоставляются с BD и BC второго.'),
         ('Как из BD·BE выделить квадрат?', 'Замени BE суммой BD+DE. Получается AB·BC=BD²+BD·DE. Для пересекающихся в D хорд AC и BE верно BD·DE=AD·DC. Вычти это произведение из обеих частей.',
          'У каждой хорды перемножают две её части до и после точки пересечения.')],
        [frame(p,'ABCD',abc+[('B','D')]),frame(p,'ABCDEO',abc+[('B','E'),('A','E')]),
         frame(p,'ABCDEO',abc+[('B','E'),('A','E')],('ABE','DBC')),frame(p,'ABCDEO',abc+[('B','E')])],
        (2,'Если AB=6, BC=10, чему равно произведение BD·BE?', ['60'],'Перемножь две стороны, прилежащие к биссектрисе.'),page=222)
    for i in [1,2,3]:
        first['model']['views'][f'step-{i}']['circles']=[dict(center=f'O__v{i}',through=f'B__v{i}')]
    h=foot(b,a,c)
    # E is the midpoint of the arc AC on the other side of AC from B.
    p.update(H=h)
    second=solution(911,'В треугольнике ABC проведи высоту BH и биссектрису BE до второго пересечения с описанной окружностью. Её центр — O. Почему BE делит угол OBH пополам?',
        'E — середина дуги AC, не содержащей B. Луч OE направлен параллельно BH, а OB=OE. Углы OBE и EBH равны.',
        'Центр соединён с двумя точками окружности отрезками равной длины. Какие стороны равнобедренного треугольника можно теперь увидеть?',
        [('Почему E равноудалена от A и C?', 'Вписанные углы ABE и EBC равны. Они стягивают равные дуги AE и EC, а значит и равные хорды. E — середина дуги AC, на которой нет B.',
          'Равным вписанным углам соответствуют равные дуги одной окружности.'),
         ('Что связывает OE с высотой BH?', 'O и E равноудалены от A и C, поэтому прямая OE — серединный перпендикуляр к AC. От O к E идём перпендикулярно AC в сторону дуги без B. От B к H идём в ту же сторону. Лучи OE и BH сонаправлены.',
          'Диаметр через середину дуги перпендикулярен хорде, стягивающей эту дугу. Если AC — диаметр, OE всё равно перпендикулярен AC.'),
         ('Какие два равенства углов завершают доказательство?', 'В треугольнике OBE радиусы OB и OE равны, поэтому ∠OBE=∠BEO. При замене обоих лучей угла BEO на противоположно направленные получаем ∠EBH. Если B, O и E на одной прямой, симметрия даёт совпадение лучей BO, BE и BH.',
          'Угол между двумя лучами сохраняется при одновременном изменении обоих направлений на противоположные.')],
        [frame(p,'ABCEOH',abc+[('B','H'),('B','E'),('B','O')]),frame(p,'ABCEO',abc+[('B','E'),('A','E'),('C','E')]),
         frame(p,'ABCEOH',abc+[('B','H'),('B','E'),('O','E')]),frame(p,'ABCEOH',abc+[('B','H'),('B','O'),('O','E'),('B','E')],('OBE',))],
        (1,'Если ∠ABC=74°, сколько градусов в угле ABE?', ['37'],'BE — внутренняя биссектриса угла B.'),page=222)
    circle_each(second,[('O','B')])
    # Equilateral triangle on the unit circle, with X on the arc BC opposite A.
    def polar(degree): return cos(radians(degree)),sin(radians(degree))
    a,b,c,x=map(polar,[90,210,330,285])
    y=coordinates(a,x,dist(c,x)/dist(a,x))
    p=dict(A=a,B=b,C=c,X=x,Y=y,O=(0,0))
    base=edges('ABC')+[('A','X'),('B','X'),('C','X')]
    third=solution(912,'Точка X произвольно выбрана на описанной окружности равностороннего ABC. Соедини X с вершинами. Обоснуй, что длина одного из трёх отрезков равна сумме длин двух других.',
        'Если X на дуге BC без A, то AX=BX+CX. Для двух других дуг меняются обозначения. При совпадении X с вершиной одно слагаемое равно нулю.',
        'Сначала установи, какая вершина находится напротив выбранной дуги. Попробуй разбить отрезок от X до этой вершины на две части.',
        [('Как разрезать AX?', 'Пусть X находится внутри дуги BC без A. Из B проведи луч BY внутри угла ABX так, чтобы ∠ABY=∠CBX. В треугольнике ABX он пересечёт сторону AX в Y.',
          'Луч BC лежит внутри угла ABX, поэтому меньший угол CBX можно отложить от BA внутрь ABX.'),
         ('Почему AY=CX?', 'Углы BAY и BCX опираются на одну хорду BX и равны. Вместе с ∠ABY=∠CBX это даёт подобие ABY и CBX. Соответствующие стороны AB и CB равны, значит коэффициент подобия равен единице и AY=CX.',
          'При таком соответствии A переходит в C, B в B, Y в X.'),
         ('Почему оставшаяся часть YX равна BX?', 'Вычти равные углы ABY и CBX из угла ABX. Получится ∠YBX=∠ABC=60°. Угол BXY равен BXA, а тот равен BCA, поскольку оба опираются на BA. У треугольника BXY два угла по 60°, значит YX=BX. Складываем AY и YX. Для X на другой дуге меняем буквы по кругу.',
          'При X в вершине два ненулевых отрезка — равные стороны исходного треугольника.')],
        [frame(p,'ABCXO',base),frame(p,'ABCXYO',base+[('B','Y')]),frame(p,'ABCXYO',base+[('B','Y')],('ABY','CBX')),
         frame(p,'ABCXYO',base+[('B','Y')],('BXY',))],
        (3,'X на дуге BC без A. Если BX=4 и CX=7, чему равно AX?', ['11'],'AX разрезан на части AY=CX и YX=BX.'),page=222)
    circle_each(third,[('O','A')])
    a,b,c,d=(-sqrt(21),2),(3,4),(sqrt(21),2),(3,-4)
    y=(-3,4); p=dict(A=a,B=b,C=c,D=d,Y=y,O=(0,0),H=(3,2))
    base=edges('ABCD')+[('A','C'),('B','D')]
    fourth=solution(913,'У вписанного четырёхугольника ABCD диагонали перпендикулярны. Почему сумма квадратов каждой пары противоположных сторон равна квадрату диаметра его окружности?',
        'Для диаметра DY получаем CD²+CY²=DY². Хорды AB и CY равны, поэтому AB²+CD²=DY². Последовательная замена букв даёт BC²+DA²=DY².',
        'Дострой диаметр через D. Как превратить одну из оставшихся длин в катет прямоугольного треугольника?',
        [('Как получить прямоугольный треугольник с гипотенузой DY?', 'Возьми Y — точку, противоположную D на окружности. Тогда ∠DCY прямой и CD²+CY²=DY². Так же DB перпендикулярна BY. По условию DB перпендикулярна AC, значит хорды BY и AC параллельны.',
          'Вписанный угол, опирающийся на диаметр, прямой.'),
         ('Почему у параллельных хорд получаются равные боковые отрезки?', 'Прямая через центр O, перпендикулярная AC, служит общей осью симметрии хорд AC и BY. Она переставляет A и C, B и Y: B и A могут быть по разные стороны оси, это выводу не мешает. Отражённый отрезок AB совпадает с CY, значит AB=CY.',
          'Перпендикуляр из центра к хорде проходит через её середину. Диаметр BY в этой задаче не требуется.'),
         ('Как записать обе суммы?', 'Подставь AB вместо CY в первое равенство. Оно даёт AB²+CD²=DY². При циклической замене вершин в том же доказательстве получим BC²+DA², справа останется квадрат той же длины диаметра. Если BD сам диаметр, то Y=B: перпендикуляр BD к AC меняет местами A и C и даёт AB=CB непосредственно.',
          'У одной окружности все диаметры равны.')],
        [frame(p,'ABCDOH',base),frame(p,'ABCDOHY',base+[('D','Y'),('C','Y'),('B','Y')],('DCY',)),
         frame(p,'ABCDOHY',base+[('B','Y'),('C','Y')]),frame(p,'ABCDOHY',base+[('D','Y'),('C','Y')],('DCY',))],
        (3,'Если диаметр равен 13, а AB=5, чему равна противоположная сторона CD?', ['12'],'CD²=13²−5². Длина положительна.'),page=222)
    circle_each(fourth,[('O','A')])
    return [first,second,third,fourth]
